function anchors(e){if(e.type==='block')return [{p:e.pos,type:'Insertion'}];let a=[];if(e.type==='circle')return [{p:e.center,type:'Center'},...[0,Math.PI/2,Math.PI,Math.PI*1.5].map(v=>({p:C.pt(e.center.x+Math.cos(v)*e.radius,e.center.y+Math.sin(v)*e.radius),type:'Quadrant'}))];if(e.type==='arc'){const ps=C.points(e);return [{p:e.center,type:'Center'},{p:ps[0],type:'Endpoint'},{p:ps.at(-1),type:'Endpoint'}];}if(e.type==='text'||e.type==='point')return [{p:e.pos,type:'Insertion'}];const ps=e.type==='line'?[e.a,e.b]:e.type==='dim'?[e.a,e.b]:(e.points||[]);for(let i=0;i<ps.length;i++){a.push({p:ps[i],type:'Endpoint'});if(i>0)a.push({p:C.mul(C.add(ps[i],ps[i-1]),.5),type:'Midpoint'});}if(e.closed&&ps.length>2)a.push({p:C.mul(C.add(ps[0],ps.at(-1)),.5),type:'Midpoint'});return a;}
