function renderLayers(){$('#layers').replaceChildren();const filter=($('#layerSearch')?.value||'').toLocaleLowerCase('en'),matches=doc.layers.filter(l=>l.name.toLocaleLowerCase('en').includes(filter));$('#moreLayers').hidden=matches.length<=layerLimit;$('#moreLayers').textContent='Show more ('+Math.min(layerLimit,matches.length)+' / '+matches.length+')';for(const l of matches.slice(0,layerLimit)){const row=document.createElement('div');row.className='layer'+(l.name===doc.activeLayer?' current':'');const color=document.createElement('input');color.type='color';color.value=l.color;color.title='Layer color';color.onchange=()=>{checkpoint();l.color=color.value;changed();};const name=document.createElement('button');name.className='lname';name.textContent=l.name;name.title=l.name+' · Make current layer';name.onclick=()=>{doc.activeLayer=l.name;refresh();};const eye=document.createElement('button');eye.className='mini'+(!l.visible?' off':'');eye.textContent='◉';eye.title=l.visible?'Hide layer':'Show layer';eye.onclick=()=>{checkpoint();l.visible=!l.visible;changed();};const lock=document.createElement('button');lock.className='mini'+(!l.locked?' off':'');lock.textContent=l.locked?'▣':'□';lock.title=l.locked?'Unlock':'Lock layer';lock.onclick=()=>{checkpoint();l.locked=!l.locked;changed();};const edit=document.createElement('button');edit.className='mini';edit.textContent='⋮';edit.title='Layer settings';edit.onclick=()=>editLayer(l);const width=document.createElement('select');width.className='lwidth';width.title='Layer lineweight (mm)';for(const value of ModernDXF.WEIGHTS){const o=document.createElement('option');o.value=value/100;o.textContent=(value/100).toFixed(2);width.append(o);}width.value=ModernDXF.weight(l.width??.25)/100;width.onchange=()=>{checkpoint();l.width=Number(width.value);changed();};row.append(color,name,width,eye,lock,edit);$('#layers').append(row);}}
