function setTool(t){window.TrimGesture?.cancel();window.EditUI?.clear();if(tool==='polyline'&&stage.length>=2&&t!==tool)commitPolyline(false);polyMode='line';polyArcMid=null;if(t==='erase'&&selection.size){eraseSelected();return;}if(['move','copy','rotate','scale','mirror'].includes(t)&&!selected().length){log('Select objects first, then start '+(Object.fromEntries(editTools)[t]||t)+'.');t='select';}dyn.first=null;dyn.second=null;commandSession.start(t);tool=t;stage=[];hoverSnap=null;if(t!=='select')lastTool=t;updateHint();refresh();render();canvas.focus();}
