canvas.addEventListener('pointerdown',e=>{if($('#dialog').open)return;canvas.focus();const p=C.pt(e.offsetX,e.offsetY);screenMouse=p;canvas.setPointerCapture(e.pointerId);if(e.button===1||(e.button===0&&space)){e.preventDefault();drag={kind:'pan',start:p,view:{...view}};return;}if(e.button!==0)return;if(tool==='trim'&&window.TrimGesture){e.preventDefault();mouse=world(p);hoverSnap=null;TrimGesture.start(mouse);drag={kind:'trim'};render();return;}if(tool==='select'){drag={kind:'select',start:p,shift:e.shiftKey};}else{mouse=applyDynamicPoint(snap(world(p)));place(C.clone(mouse));}});
