 $('#busy strong').textContent=kind==='dwg'?'Writing and verifying DWG…':'Saving drawing…';$('#busy').hidden=false;$('#cancelOpen').hidden=true;
 const content=kind==='hcad'?JSON.stringify(doc,null,2):['dxf','dwg'].includes(kind)?ModernDXF.serialize(doc):kind==='pdf'?JSON.stringify({doc,settings:plotData.settings,ids:plotData.ids}):IO.svg(doc);
