 if(saved?.recentId)window.HomeUI?.record(saved.recentId);if(kind==='hcad'){doc.name=name.replace(/\.hcad$/i,'');setDirty(false);refresh();DocumentTabs.saved(saved);}log(name+' saved.');return true;
