async function showReport(){const r=doc.importReport;if(!r)return;const rows=Object.entries(r.skipped||{}).map(([k,v])=>`<tr><td>${escapeHTML(k)}</td><td>${v} skipped</td></tr>`).join('');await modal('Import report',`<p><strong>${escapeHTML(r.file)}</strong><br>${r.loaded} objects · ${doc.layers.length} layers</p><p class="warning">Supported 2D model-space objects are imported. Paper space, external references, 3D solids and custom/proxy objects are not fully supported. Complete DWG equivalence is not guaranteed.</p>${rows?'<table>'+rows+'</table>':''}${r.readerUnknown?`<p>Objects unknown to the reader: ${r.readerUnknown}</p>`:''}${(r.notes||[]).map(s=>`<p>• ${escapeHTML(s)}</p>`).join('')}<p class="muted">The source DWG is preserved. Save your work as HCAD, DXF or DWG 2000.</p>`);}
async function newDoc(){if(DocumentTabs.locked())return;const next=C.create();let n=1;while(DocumentTabs.list().some(t=>t.doc.name==='Drawing '+n))n++;next.name='Drawing '+n;DocumentTabs.add(next,{replaceEmpty:!!window.HomeUI?.visible()});window.HomeUI?.hide();}
function undo(){if(history.undo(doc)){indexDirty=true;selection.clear();setTool('select');setDirty();changed();}}
function redo(){if(history.redo(doc)){indexDirty=true;selection.clear();setTool('select');setDirty();changed();}}
async function demo(){if(DocumentTabs.locked())return;DocumentTabs.add(C.create(),{replaceEmpty:!!window.HomeUI?.visible()});window.HomeUI?.hide();doc.name='Sample · Office';doc.layers=[{name:'0',color:'#e4eaf2',visible:true,locked:false,width:.25,lineType:'CONTINUOUS'},{name:'A-DUVAR',color:'#ccd8e4',visible:true,locked:false,width:.6,lineType:'CONTINUOUS'},{name:'A-MOBILYA',color:'#65bda6',visible:true,locked:false,width:.25,lineType:'CONTINUOUS'},{name:'A-OLCU',color:'#d5b880',visible:true,locked:false,width:.15,lineType:'CONTINUOUS'},{name:'A-YAZI',color:'#b1c1d1',visible:true,locked:false,width:.18,lineType:'CONTINUOUS'}];const add=(l,e)=>doc.entities.push({id:C.id(),layer:l,...e}),r=(l,x,y,w,h)=>add(l,rectEntity(C.pt(x,y),C.pt(x+w,y+h))),line=(l,x,y,u,v)=>add(l,{type:'line',a:C.pt(x,y),b:C.pt(u,v)});
 r('A-DUVAR',0,0,6000,4200);r('A-DUVAR',180,180,5640,3840);r('A-MOBILYA',500,2700,1600,800);r('A-MOBILYA',3900,2700,1600,800);r('A-MOBILYA',600,450,1700,750);r('A-MOBILYA',4500,400,750,1400);r('A-MOBILYA',2500,1000,1000,500);for(const x of [1300,4700]){add('A-MOBILYA',{type:'circle',center:C.pt(x,2250),radius:280});r('A-MOBILYA',x-250,3050,500,120);}add('A-MOBILYA',{type:'circle',center:C.pt(3200,3100),radius:330});for(const x of [2300,3500]){r('A-MOBILYA',x,3720,600,300);}line('A-MOBILYA',2400,200,2400,1100);add('A-MOBILYA',{type:'arc',center:C.pt(2400,200),radius:900,start:0,end:Math.PI/2});add('A-YAZI',{type:'text',pos:C.pt(2250,1900),height:155,text:'OFFICE',rotation:0});add('A-YAZI',{type:'text',pos:C.pt(2480,1660),height:110,text:'25.20 m²',rotation:0});add('A-OLCU',{type:'dim',a:C.pt(0,0),b:C.pt(6000,0),offset:C.pt(0,-550),height:100});add('A-OLCU',{type:'dim',a:C.pt(6000,0),b:C.pt(6000,4200),offset:C.pt(6650,0),height:100});doc.activeLayer='A-DUVAR';$('#textHeight').value=100;$('#gridStep').value=100;selection.clear();resetHistory();stage=[];tool='select';currentFileType='SAMPLE PROJECT';setDirty(true);refresh();fit();log('Sample opened. Select objects to edit them.');}
async function help(){await modal('OpenCAD · Help',`<h3>Drawing and editing</h3><p>L LINE · PL PLINE · REC RECTANG · C CIRCLE · A ARC · T TEXT · DIM · H HATCH. Coordinates: 100,200; relative: @500,0; polar: @500&lt;30. F8 toggles Ortho; rectangle corners remain free in both axes. F12 toggles dynamic input.</p><p>TR TRIM: start without a selection to use all visible cutting edges, then click the part to remove, or hold the left mouse button and sweep across multiple parts. Release applies the stroke; Esc cancels the preview; one Undo reverses the whole stroke. You can also preselect cutting edges. Lines, arcs, circles and straight/curved polylines are supported. EX EXTEND: click near the end to extend to the nearest boundary. Editing is available on any visible, unlocked layer. Locked geometry can be a cutting edge.</p><p>M MOVE · CO COPY · RO ROTATE · SC SCALE · MI MIRROR · E ERASE. Select objects before these commands. FILLET / FI, CHAMFER / CHA, ARRAY / AR, BREAK / BR, BREAKATPOINT / BRP, LENGTHEN / LEN and STRETCH / S provide their supported 2D operations. Enter finishes, Esc cancels. Ctrl+Z / Ctrl+Y undo and redo.</p><h3>Blocks and polylines</h3><p>B BLOCK creates a block from the selection with a name and base point. Imported blocks remain single selectable objects, including nested blocks. X EXPLODE separates one level. PEDIT / PE edits polyline vertices; JOIN / J joins connected paths. Block members keep their layers. Shared definition editing, dynamic blocks and attribute editing are not implemented; export creates a separate definition per instance.</p><h3>Drawing tabs</h3><p>New and Open create independent drawing tabs. Use + for a blank tab or the adjacent Open button for another file. Ctrl+Tab / Ctrl+Shift+Tab switch drawings; Ctrl+W closes the active tab with Save project, Discard and Cancel choices. Each tab keeps its layers, view and undo history. Autosave recovers all open tabs; undo history is not restored after restarting.</p><h3>Files and output</h3><p>Save HCAD to retain editable project data. Export supports DXF/DWG 2000 and scaled PDF. Plot offers paper, orientation, window/selection/extents, scale and offsets. Print PDFs at 100% / Actual size. Display contrast affects the screen only.</p><p>DWG engine settings can select a separately installed ODA File Converter. The bundled LibreDWG writer is experimental and other CAD applications may request recovery. Saving checks object counts, block structure, extents and layer weights; this is not an AutoCAD compatibility certificate.</p><h3>Current limits</h3><p>This is a 2D CAD application with a subset of AutoCAD-style commands. 3D solids, paper space editing, XREF attachment, dynamic blocks, SHX fonts and LISP are not supported. Imported splines and hatch boundaries are approximated as polylines. Unsupported objects appear in the import report. Keep source drawings.</p>`);}

const actions={dwgSettings,block:createBlock,display:displayDialog,layerReport:layerReport,pedit:editPolyline,join:joinPolylines,explode:explodePolylines,drafting:draftingDialog,ucs:ucsDialog,fence:()=>setTool('fence'),new:newDoc,open:openFile,save:()=>save(),export:async()=>{const r=await modal('Export','<p>Choose an export format.</p><p class="muted">DWG/DXF include all layers; SVG/PDF include visible layers. PDF opens paper and scale settings.</p>',[['dwg','DWG 2000'],['dxf','DXF 2000'],['svg','SVG'],['pdf','Scaled PDF']]);if(['dwg','dxf','svg','pdf'].includes(r.action))save(r.action);},help,undo,redo,fit,zoomIn:()=>zoom(1.25),zoomOut:()=>zoom(.8),addLayer:newLayer,report:showReport,demo,enter:()=>runCommand()};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tool)setTool(b.dataset.tool);if(b.dataset.action)actions[b.dataset.action]?.();if(b.dataset.toggle){toggleFlag(b.dataset.toggle);refresh();render();}});
