const aliases={F:'fence',FENCE:'fence',L:'line',LINE:'line',PL:'polyline',PLINE:'polyline',POLYLINE:'polyline',REC:'rect',RECTANG:'rect',C:'circle',CIRCLE:'circle',A:'arc',ARC:'arc',T:'text',TEXT:'text',DIM:'dim',DIMALIGNED:'dim',H:'hatch',HATCH:'hatch',M:'move',MOVE:'move',CO:'copy',COPY:'copy',RO:'rotate',ROTATE:'rotate',SC:'scale',SCALE:'scale',MI:'mirror',MIRROR:'mirror',O:'offset',OFFSET:'offset',TR:'trim',TRIM:'trim',EX:'extend',EXTEND:'extend',E:'erase',ERASE:'erase',DI:'measure',DIST:'measure'};
function parsePoint(s){const relative=s.startsWith('@');if(relative)s=s.slice(1);const base=relative?(stage.at(-1)||P.ucs(doc).origin):C.pt(),u=P.ucs(doc);let match=s.match(/^(-?\d*\.?\d+(?:e[+-]?\d+)?)\s*,\s*(-?\d*\.?\d+(?:e[+-]?\d+)?)$/i),q;if(match)q=C.pt(Number(match[1]),Number(match[2]));else{match=s.match(/^(-?\d*\.?\d+)\s*<\s*(-?\d*\.?\d+)$/);if(match){const a=Number(match[2])*Math.PI/180,r=Number(match[1]);q=C.pt(r*Math.cos(a),r*Math.sin(a));}}if(!q||!Number.isFinite(q.x)||!Number.isFinite(q.y))return null;return relative?C.add(base,P.toWorld(q,u,true)):P.toWorld(q,u);}

async function runCommand(){const field=$('#command'),s=field.value.trim();field.value='';if(!s){if(['trim','extend'].includes(tool)){finish();return;}if(tool==='advanced'||stage.length)finish();else if(lastTool==='advanced')window.EditUI.finish();else setTool(lastTool);return;}commandHistory.push(s);historyIndex=commandHistory.length;log('> '+s);const upper=s.toUpperCase();if(tool==='polyline'&&stage.length){if(['A','ARC','L','LINE'].includes(upper)){polyMode=['A','ARC'].includes(upper)?'arc':'line';polyArcMid=null;updateHint();render();return;}if(['U','UNDO'].includes(upper)){if(polyArcMid)polyArcMid=null;else if(stage.length>1){stage.pop();stage.at(-1).bulge=0;}updateHint();render();return;}}if((upper==='C'||upper==='CLOSE')&&['line','polyline'].includes(tool)&&stage.length>=3){finish(true);return;}const p=parsePoint(s);if(p){if(tool==='select')setTool('line');await place(p);return;}
 if(stage.length&&Number.isFinite(Number(s))){const n=Number(s),base=stage.at(-1);if(tool==='circle'&&n>0){place(C.pt(stage[0].x+n,stage[0].y));return;}if(['line','polyline','measure'].includes(tool)&&n>0){let dir=C.sub(mouse,base),len=Math.hypot(dir.x,dir.y);if(len<1e-8){dir=C.pt(1,0);len=1;}place(C.add(base,C.mul(dir,n/len)));return;}}
 if(window.EditUI?.command(upper))return;
 if(aliases[upper])setTool(aliases[upper]);else if(['Z','ZE','ZOOM'].includes(upper))fit();else if(['U','UNDO'].includes(upper))undo();else if(upper==='REDO')redo();else if(['LA','LAYER'].includes(upper))newLayer();else if(['SAVE','QSAVE'].includes(upper))save();else if(upper==='OPEN')openFile();else if(upper==='NEW')newDoc();else if(['PLOT','PRINT'].includes(upper))plotDialog();else if(['PE','PEDIT'].includes(upper))editPolyline();else if(['J','JOIN'].includes(upper))joinPolylines();else if(['B','BLOCK'].includes(upper))createBlock();else if(upper==='DISPLAY')displayDialog();else if(['X','EXPLODE'].includes(upper))explodePolylines();else if(upper==='UCS')ucsDialog();else if(upper==='WCS'){checkpoint();delete doc.ucs;changed();log('World coordinate system active.');}else if(['DSETTINGS','OSNAP','POLAR'].includes(upper))draftingDialog();else if(['P','SELECTPREVIOUS'].includes(upper))useSelection(previousSelection.slice());else if(['LAST','SELECTLAST'].includes(upper))useSelection(doc.entities.length?[doc.entities.at(-1).id]:[]);else if(upper==='HELP')help();else log('Unknown command. Press F1 for the command list.');}
$('#command').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();e.stopPropagation();runCommand();}if(e.key==='ArrowUp'){e.preventDefault();historyIndex=Math.max(0,historyIndex-1);e.target.value=commandHistory[historyIndex]||'';}if(e.key==='ArrowDown'){historyIndex=Math.min(commandHistory.length,historyIndex+1);e.target.value=commandHistory[historyIndex]||'';}});
document.addEventListener('keydown',e=>{if(fileOpening||fileSaving||$('#dialog').open)return;if(window.HomeUI?.visible()&&!e.ctrlKey&&!e.metaKey)return;const input=['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName);if(e.key==='Escape'){e.preventDefault();rememberSelection();if(tool==='polyline')commitPolyline(false);stage=[];selection.clear();pendingPlotSettings=null;setTool('select');$('#command').value='';return;}if(e.key==='F1'){e.preventDefault();help();return;}const ft={F3:'osnap',F7:'grid',F8:'ortho',F9:'snapGrid',F10:'polar',F12:'dynamic'}[e.key];if(ft){e.preventDefault();toggleFlag(ft);refresh();render();return;}if(e.ctrlKey||e.metaKey){const k=e.key.toLowerCase();if(['o','s','n','p'].includes(k)){e.preventDefault();({o:openFile,s:()=>save(),n:newDoc,p:()=>plotDialog()})[k]();return;}if(!input&&['z','y','a','c','v'].includes(k)){e.preventDefault();if(k==='z')undo();if(k==='y')redo();if(k==='a'){useSelection(doc.entities.filter(editable).map(e=>e.id));}if(k==='c'){clipboard=C.clone(selected());log(clipboard.length+' objects copied to clipboard.');}if(k==='v'&&clipboard.length){const b=C.bounds(clipboard);checkpoint();selection.clear();for(const e of clipboard){if(!doc.layers.some(l=>l.name===e.layer))e.layer=doc.activeLayer;const n=C.translate(e,C.pt(-b.x0,-b.y0));doc.entities.push(C.duplicate(n));selection.add(n.id);}tool='move';stage=[C.pt()];updateHint();changed();}return;}}if(input)return;if(flags.dynamic&&tool!=='select'&&/^[0-9.\-]$/.test(e.key)&&!e.altKey){e.preventDefault();const field=$('#dynValue1');field.focus();field.value=e.key;field.dispatchEvent(new Event('input',{bubbles:true}));return;}if(e.key==='Tab'&&flags.dynamic&&tool!=='select'){e.preventDefault();$('#dynValue1').focus();$('#dynValue1').select();return;}if(e.key==='Delete'){e.preventDefault();eraseSelected();return;}if(e.code==='Space'){e.preventDefault();space=true;return;}if(e.key==='Enter'){e.preventDefault();if(tool==='advanced'||stage.length)finish();else if(lastTool==='advanced')window.EditUI.finish();else setTool(lastTool);return;}if(e.key.length===1&&!e.altKey){$('#command').focus();$('#command').value=e.key;e.preventDefault();}});
