function toggleFlag(name){flags[name]=!flags[name];if(flags[name]&&name==='ortho')flags.polar=false;if(flags[name]&&name==='polar')flags.ortho=false;}
async function ucsDialog(){const u=P.ucs(doc),r=await modal('User coordinate system — 2D UCS',`<p>Enter the new origin in world coordinates. Geometry stays in place; subsequent coordinates and polar/Ortho directions use this UCS.</p><label>Start X<input name="x" type="number" step="any" value="${u.origin.x}"></label><label>Start Y<input name="y" type="number" step="any" value="${u.origin.y}"></label><label>X axis angle (degrees)<input name="angle" type="number" step="any" value="${u.angle*180/Math.PI}"></label>`,[['world','World (WCS)'],['cancel','Cancel'],['ok','Apply']]);if(r.action==='cancel')return;if(r.action==='world'){checkpoint();delete doc.ucs;}else{const x=Number(r.values.x),y=Number(r.values.y),angle=Number(r.values.angle);if(![x,y,angle].every(Number.isFinite)||Math.abs(x)>1e12||Math.abs(y)>1e12){log('Enter valid coordinates and an angle.');return;}checkpoint();doc.ucs={origin:C.pt(x,y),angle:angle*Math.PI/180};}stage=[];changed();log(doc.ucs?'UCS active. Absolute and relative input use these axes.':'World coordinate system active.');}
async function draftingDialog(){const prefs=doc.drafting||{},modes=prefs.modes||P.DEFAULT_MODES;const promise=modal('Drafting settings',`<div class="drafting-grid"><fieldset><legend>Object snaps (F3)</legend>${Object.entries(P.MODES).map(([key,name])=>`<label class="check"><input type="checkbox" name="snap_${key}" ${modes.includes(key)?'checked':''}>${name}</label>`).join('')}</fieldset><fieldset><legend>Polar tracking (F10)</legend><label>Angle increment (degrees)<input name="polarAngle" type="number" min="1" max="180" step="any" value="${prefs.polarAngle||30}"></label><p>Polar tracking snaps within 4° of a target angle. Ortho and polar tracking are mutually exclusive.</p><label>Axis lock<select name="axis"><option value="none">Free</option><option value="x">UCS X axis</option><option value="y">UCS Y axis</option></select></label><p>Specify a base point for perpendicular and tangent snaps. Discrete snap points take priority over nearest.</p></fieldset></div>`,[['cancel','Cancel'],['ok','Apply']]);$('#dialogbody [name=axis]').value=prefs.axis||'none';let checked=modes.slice();const collect=()=>checked=[...$('#dialogbody').querySelectorAll('[name^=snap_]:checked')].map(e=>e.name.slice(5));$('#dialogbody').querySelectorAll('[name^=snap_]').forEach(e=>e.addEventListener('change',collect));const r=await promise;if(r.action!=='ok')return;const a=Number(r.values.polarAngle);if(!Number.isFinite(a)||a<1||a>180){log('The polar angle must be between 1° and 180°.');return;}checkpoint();doc.drafting={polarAngle:a,axis:r.values.axis,modes:checked};changed();}
async function joinPolylines(){const els=selected();if(els.length<2){log('JOIN: Select at least two lines, arcs or open polylines.');return;}const value=await ask('Join polylines — JOIN','Endpoint tolerance ('+doc.units+'). The result uses the first object layer.','0.001');if(value===null)return;try{const result=Polyline.join(els,Number(value)),ids=new Set(els.map(e=>e.id));checkpoint();result.id=C.id();doc.entities=doc.entities.filter(e=>!ids.has(e.id));doc.entities.push(result);selection=new Set([result.id]);changed();log(els.length+' objects joined into one polyline.');}catch(e){log(e.message);}}
function explodePolylines(){const els=selected().filter(e=>['block','polyline'].includes(e.type));if(!els.length){log('EXPLODE: Select a block or polyline.');return;}const pieces=els.flatMap(e=>e.type==='block'?C.explodeBlock(e):Polyline.explode(e)),ids=new Set(els.map(e=>e.id));checkpoint();doc.entities=doc.entities.filter(e=>!ids.has(e.id)).concat(pieces);selection=new Set(pieces.map(e=>e.id));changed();log('Selection exploded one level. Nested blocks are preserved.');}
async function editPolyline(){let els=selected();if(els.length!==1||!['polyline','line','arc'].includes(els[0].type)){log('PEDIT: Select a POLYLINE, LINE or ARC first.');return;}const target=els[0];let edited=Polyline.fromEntity(target),node=0;const u=P.ucs(doc);const answer=modal('Edit polyline — PEDIT',`<p>Vertices are shown in the current UCS. Apply commits all changes as one undoable operation.</p><div class="pedit-grid"><label>Vertex<select id="peNode"></select></label><label>State<select id="peClosed"><option value="0">Open</option><option value="1">Closed</option></select></label><label>X<input id="peX" type="number" step="any"></label><label>Y<input id="peY" type="number" step="any"></label><label>Next segment arc angle (°)<input id="peAngle" type="number" step="any" min="-359" max="359"></label></div><p class="muted">0° creates a straight segment. Positive angles are counterclockwise. Deleting a vertex straightens the preceding segment.</p><div class="precision-actions"><button type="button" id="peUpdate">Update vertex</button><button type="button" id="peInsert">Insert midpoint vertex</button><button type="button" id="peDelete">Delete vertex</button><button type="button" id="peReverse">Reverse direction</button></div><p id="peSummary" aria-live="polite"></p>`,[['cancel','Cancel'],['ok','Apply']]);
 const show=()=>{node=Math.min(node,edited.points.length-1);$('#peNode').innerHTML=edited.points.map((p,i)=>`<option value="${i}">Vertex ${i+1}</option>`).join('');$('#peNode').value=node;$('#peClosed').value=edited.closed?'1':'0';const v=edited.points[node],p=P.toLocal(v,u);$('#peX').value=p.x;$('#peY').value=p.y;$('#peAngle').value=4*Math.atan(v.bulge||0)*180/Math.PI;$('#peAngle').disabled=!edited.closed&&node===edited.points.length-1;$('#peSummary').textContent=`${edited.points.length} vertices · Length ${Polyline.length(edited).toFixed(3)} ${doc.units}`;};
 const update=()=>{const x=Number($('#peX').value),y=Number($('#peY').value),angle=Number($('#peAngle').value);if(![x,y,angle].every(Number.isFinite)||Math.abs(angle)>=360||Math.abs(x)>1e12||Math.abs(y)>1e12)throw Error('Enter valid coordinates and an angle between -360° and 360°.');const p=P.toWorld(C.pt(x,y),u);edited.points[node]={...p,bulge:$('#peAngle').disabled?0:Math.tan(angle*Math.PI/720)};};
 const action=fn=>{try{update();fn();show();}catch(e){$('#peSummary').textContent=e.message;}};
 $('#peNode').onchange=e=>{node=Number(e.target.value);show();};$('#peClosed').onchange=e=>{if(e.target.value==='1'&&edited.points.length<3){$('#peSummary').textContent='At least 3 vertices are required to close a polyline.';e.target.value='0';return;}edited.closed=e.target.value==='1';if(!edited.closed)edited.points.at(-1).bulge=0;show();};$('#peUpdate').onclick=()=>action(()=>{});$('#peInsert').onclick=()=>action(()=>{edited=Polyline.split(edited,node);node++;});$('#peDelete').onclick=()=>action(()=>{edited=Polyline.remove(edited,node);});$('#peReverse').onclick=()=>action(()=>{edited=Polyline.reverse(edited);node=0;});show();
 const r=await answer;if(r.action!=='ok')return;try{update();if(edited.points.some((p,i)=>i>0&&C.dist(p,edited.points[i-1])<1e-8))throw Error('Consecutive vertices cannot occupy the same point.');checkpoint();Object.assign(target,edited);changed();}catch(e){log('PEDIT was not applied: '+e.message);}}
function dynamicPolar(){return stage.length&&['line','polyline','measure','move','copy','circle'].includes(tool);}
function dynamicValues(){const u=P.ucs(doc);if(dynamicPolar()){const q=P.toLocal(C.sub(mouse,stage.at(-1)),u,true);return [Math.hypot(q.x,q.y),(Math.atan2(q.y,q.x)*180/Math.PI+360)%360];}const p=P.toLocal(mouse,u);return [p.x,p.y];}
function applyDynamicPoint(p){if(!flags.dynamic)return p;const u=P.ucs(doc);if(dynamicPolar()){const base=stage.at(-1),q=P.toLocal(C.sub(p,base),u,true),r=dyn.first??Math.hypot(q.x,q.y),a=(dyn.second??Math.atan2(q.y,q.x)*180/Math.PI)*Math.PI/180;return C.add(base,P.toWorld(C.pt(r*Math.cos(a),r*Math.sin(a)),u,true));}const q=P.toLocal(p,u);return P.toWorld(C.pt(dyn.first??q.x,dyn.second??q.y),u);}
function updateDynamicInput(){const box=$('#dynamicInput'),shown=flags.dynamic&&!['select','erase','offset','trim','extend','hatch','fence','plotwindow'].includes(tool)&&!$('#dialog').open;box.hidden=!shown;if(!shown)return;const polar=dynamicPolar(),values=dynamicValues();$('#dynLabel1').textContent=polar?'L':'X';$('#dynLabel2').textContent=polar?'°':'Y';$('#dynCaption').textContent=polar?(tool==='circle'?'Radius / direction':tool==='polyline'&&polyMode==='arc'?'Arc point — distance / direction':'Length / angle')+' · '+doc.units+' · UCS':'Point coordinates · '+doc.units+' · UCS';for(const [i,key]of ['first','second'].entries()){const el=$('#dynValue'+(i+1));if(document.activeElement!==el)el.value=(dyn[key]??values[i]).toFixed(3);el.classList.toggle('locked',dyn[key]!==null);}if(!box.contains(document.activeElement)){box.style.left=Math.max(8,Math.min(cw-280,screenMouse.x+24))+'px';box.style.top=Math.max(8,Math.min(ch-98,screenMouse.y+24))+'px';}}
for(const [i,key]of ['first','second'].entries()){const input=$('#dynValue'+(i+1));input.addEventListener('focus',()=>input.select());input.addEventListener('input',()=>{const raw=input.value.trim().replace(',','.'),n=raw===''?null:Number(raw);if(n===null||Number.isFinite(n)&&Math.abs(n)<1e12&&(!dynamicPolar()||key!=='first'||n>0)){dyn[key]=n;$('#dynHint').textContent='Tab: next field · Enter: place point';mouse=applyDynamicPoint(snap(world(screenMouse)));render();}else $('#dynHint').textContent='Enter a valid number; length must be positive.';});input.addEventListener('keydown',async e=>{if(e.key==='Tab'){e.preventDefault();e.stopPropagation();const other=$('#dynValue'+(i===0?2:1));other.focus();other.select();}if(e.key==='Escape'){e.preventDefault();e.stopPropagation();dyn.first=null;dyn.second=null;canvas.focus();render();}if(e.key==='Enter'){e.preventDefault();e.stopPropagation();const raw=input.value.trim().replace(',','.');if(!raw||!Number.isFinite(Number(raw))||dynamicPolar()&&i===0&&Number(raw)<=0){$('#dynHint').textContent='Enter a valid value.';return;}dyn[key]=Number(raw);const point=applyDynamicPoint(mouse);await place(point);canvas.focus();render();}});}
async function layerReport(){
 const parents=new Map();for(const b of C.walk(doc.entities))if(b.type==='block')for(const c of b.children)parents.set(c.id,b);const reveal=e=>{e.sourceVisible=true;const l=layerLookup.get(e.layer);if(l)l.visible=true;for(const name of e.parentLayers||[]){const parent=layerLookup.get(name);if(parent)parent.visible=true;}const owner=parents.get(e.id);if(owner)reveal(owner);};const groups=new Map(),reports=new Map((doc.importReport?.layers||[]).map(r=>[r.name,r]));for(const e of C.walk(doc.entities)){if(!groups.has(e.layer))groups.set(e.layer,[]);groups.get(e.layer).push(e);}
 const answer=modal('Layer inspection',`<p>Inspect parent block layers, object visibility and skipped types. Show and fit reveals objects on the selected layer and required parent layers.</p><div class="precision-actions"><input id="layerFilter" placeholder="Search layer names…" aria-label="Search layer names"><button type="button" id="showAllLayers">Show all layers</button></div><table class="layer-report-table"><thead><tr><th>Layer</th><th>Visible / total</th><th>Hidden reason</th><th>Skipped</th><th></th></tr></thead><tbody id="layerReportRows"></tbody></table><p id="layerReportCount"></p><p class="muted">${doc.importReport?.paperCount||0} paper-space objects were excluded from model space. Showing layers cannot restore unresolved XREF, 3D or proxy objects.</p>`,[['cancel','Close']]);
 const rows=()=>{const query=$('#layerFilter').value.toLocaleLowerCase('en'),matches=doc.layers.filter(l=>l.name.toLocaleLowerCase('en').includes(query));$('#layerReportRows').replaceChildren();$('#layerReportCount').textContent=matches.length>200?'Showing the first 200 layers. Refine the search.':matches.length+' layers';for(const l of matches.slice(0,200)){const entities=groups.get(l.name)||[],visibleCount=entities.reduce((n,e)=>n+(entityVisible(e)?1:0),0),reasons=[];if(!l.visible)reasons.push('Layer is off');if(entities.some(e=>e.sourceVisible===false))reasons.push('Object is hidden');if(entities.some(e=>(e.parentLayers||[]).some(n=>!layerLookup.get(n)?.visible)))reasons.push('Parent block layer is off');const skipped=Object.entries(reports.get(l.name)?.skipped||{}).map(([k,v])=>k+': '+v).join(', '),tr=document.createElement('tr');tr.innerHTML=`<td>${escapeHTML(l.name)}${l.locked?' 🔒':''}</td><td>${visibleCount} / ${entities.length}</td><td>${escapeHTML(reasons.join(', ')||'—')}</td><td>${escapeHTML(skipped||'—')}</td><td><button type="button">Show and fit</button></td>`;tr.querySelector('button').disabled=!entities.length;tr.querySelector('button').onclick=()=>{const needs=!l.visible||entities.some(e=>!entityVisible(e));if(needs){checkpoint();l.visible=true;for(const e of entities){reveal(e);}changed();}const bounds={x0:Infinity,y0:Infinity,x1:-Infinity,y1:-Infinity};for(const e of entities){const b=index().byId.get(e.id)||P.bounds(e);bounds.x0=Math.min(bounds.x0,b.x0);bounds.y0=Math.min(bounds.y0,b.y0);bounds.x1=Math.max(bounds.x1,b.x1);bounds.y1=Math.max(bounds.y1,b.y1);}view.scale=Math.min((cw-100)/Math.max(1,bounds.x1-bounds.x0),(ch-100)/Math.max(1,bounds.y1-bounds.y0));view.x=cw/2-(bounds.x0+bounds.x1)/2*view.scale;view.y=ch/2+(bounds.y0+bounds.y1)/2*view.scale;$('#dialog').close('cancel');render();};$('#layerReportRows').append(tr);}};
 $('#layerFilter').oninput=rows;$('#showAllLayers').onclick=()=>{checkpoint();for(const l of doc.layers)l.visible=true;changed();rows();};rows();await answer;render();}

$('#layerSearch').oninput=()=>{layerLimit=100;renderLayers();};$('#moreLayers').onclick=()=>{layerLimit+=100;renderLayers();};
$('#cancelOpen').onclick=()=>window.desktop?.cancelOpen?.();window.desktop?.onOpenProgress?.(phase=>{$('#busy strong').textContent=phase;});
